                    </div>

                    {/* Important Info */}
                    <div className={`p-4 rounded-2xl ${
                      isDarkMode ? 'bg-blue-900/30 border border-blue-800/50' : 'bg-blue-50 border border-blue-200'
                    }`}>
                      <div className="flex items-start">
                        <svg className="w-5 h-5 text-blue-500 mr-3 mt-0.5" fill="none" stroke="currentColor" viewBox="0 0 24 24">
                          <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M13 16h-1v-4h-1m1-4h.01M21 12a9 9 0 11-18 0 9 9 0 0118 0z" />
                        </svg>
                        <div>
                          <h5 className={`font-semibold mb-1 ${isDarkMode ? 'text-white' : 'text-gray-800'}`}>
                            Important Information
                          </h5>
                          <ul className={`text-sm space-y-1 ${isDarkMode ? 'text-gray-300' : 'text-gray-600'}`}>
                            <li>• Subscription starts immediately</li>
                            <li>• You can pause/resume anytime</li>
                            <li>• No cancellation fees</li>
                            <li>• Free delivery included</li>
                          </ul>
                        </div>
                      </div>
                    </div>

                    {/* Payment Info */}
                    <div className={`p-4 rounded-2xl ${
                      isDarkMode ? 'bg-gray-700/50' : 'bg-gray-50'
                    }`}>
                      <div className="flex items-center">
                        <svg className="w-5 h-5 text-yellow-500 mr-3" fill="none" stroke="currentColor" viewBox="0 0 24 24">
                          <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M3 10h18M7 15h1m4 0h1m-7 4h12a3 3 0 003-3V8a3 3 0 00-3-3H6a3 3 0 00-3 3v8a3 3 0 003 3z" />
                        </svg>
                        <div>
                          <h5 className={`font-semibold ${isDarkMode ? 'text-white' : 'text-gray-800'}`}>
                            Payment Method
                          </h5>
                          <p className={`text-sm ${isDarkMode ? 'text-gray-400' : 'text-gray-600'}`}>
                            Auto-debit from your registered payment method
                          </p>
                        </div>
                      </div>
                    </div>
                  </div>
                ) : null;
              })()}
            </div>

            {/* Modal Footer */}
            <div className="p-6 border-t border-gray-200/20 dark:border-gray-700/20">
              <div className="flex gap-3">
                <button
                  onClick={() => setSubscriptionModal(false)}
                  className={`flex-1 py-3 px-4 rounded-xl font-semibold transition-colors ${
                    isDarkMode 
                      ? 'bg-gray-700 hover:bg-gray-600 text-white' 
                      : 'bg-gray-100 hover:bg-gray-200 text-gray-800'
                  }`}
                >
                  Cancel
                </button>
                <button
                  onClick={createSubscriptionHandler}
                  disabled={loadingSubscription}
                  className="flex-1 py-3 px-4 bg-gradient-to-r from-primary-500 to-secondary-500 text-white font-semibold rounded-xl hover:from-primary-600 hover:to-secondary-600 transition-all duration-300 disabled:opacity-50 disabled:cursor-not-allowed"
                >
                  {loadingSubscription ? (
                    <span className="flex items-center justify-center">
                      <svg className="animate-spin -ml-1 mr-3 h-5 w-5 text-white" xmlns="http://www.w3.org/2000/svg" fill="none" viewBox="0 0 24 24">
                        <circle className="opacity-25" cx="12" cy="12" r="10" stroke="currentColor" strokeWidth="4"></circle>
                        <path className="opacity-75" fill="currentColor" d="M4 12a8 8 0 018-8V0C5.373 0 0 5.373 0 12h4zm2 5.291A7.962 7.962 0 014 12H0c0 3.042 1.135 5.824 3 7.938l3-2.647z"></path>
                      </svg>
                      Processing...
                    </span>
                  ) : (
                    'Confirm Subscription'
                  )}
                </button>
              </div>
            </div>
          </div>
        </div>
      )}

      {/* QR Code Payment Modal */}
      {qrCodeModal && qrCodeData && (
        <div className="fixed inset-0 bg-black/50 backdrop-blur-sm flex items-center justify-center z-50 p-4">
          <div className={`relative max-w-md w-full rounded-3xl shadow-2xl ${
            isDarkMode ? 'bg-gray-800 border border-gray-700' : 'bg-white border border-gray-200'
          }`}>
            
            {/* Modal Header */}
            <div className="p-6 border-b border-gray-200/20 dark:border-gray-700/20">
              <div className="flex items-center justify-between">
                <h3 className={`text-2xl font-bold ${isDarkMode ? 'text-white' : 'text-gray-800'}`}>
                  Scan QR Code for Payment
                </h3>
                <button
                  onClick={() => setQrCodeModal(false)}
                  className={`p-2 rounded-full transition-colors ${
                    isDarkMode ? 'hover:bg-gray-700' : 'hover:bg-gray-100'
                  }`}
                >
                  <svg className="w-6 h-6" fill="none" stroke="currentColor" viewBox="0 0 24 24">
                    <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M6 18L18 6M6 6l12 12" />
                  </svg>
                </button>
              </div>
            </div>

            {/* Modal Body */}
            <div className="p-6">
              <div className="text-center space-y-4">
                {/* QR Code Image */}
                <div className="flex justify-center">
                  {qrCodeData ? (
                    <div className={`p-4 rounded-2xl ${
                      isDarkMode ? 'bg-white' : 'bg-gray-50'
                    }`}>
                      <img 
                        src={qrCodeData} 
                        alt="Payment QR Code" 
                        className="w-64 h-64"
                      />
                    </div>
                  ) : (
                    <div className={`p-8 rounded-2xl text-center ${
                      isDarkMode ? 'bg-red-900/20 border border-red-800/50' : 'bg-red-50 border border-red-200'
                    }`}>
                      <svg className="w-16 h-16 text-red-500 mx-auto mb-4" fill="none" stroke="currentColor" viewBox="0 0 24 24">
                        <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M12 8v4m0 4h.01M12 21l-1-1m0-4v.01M12 17l4-4m4 4h.01M5 19H4" />
                      </svg>
                      <h5 className={`font-semibold mb-2 ${isDarkMode ? 'text-white' : 'text-gray-800'}`}>
                        QR Code Generation Failed
                      </h5>
                      <p className={`text-sm ${isDarkMode ? 'text-gray-300' : 'text-gray-600'}`}>
                        Unable to generate QR code. Please try again or contact support.
                      </p>
                      <button
                        onClick={() => setQrCodeModal(false)}
                        className={`mt-4 px-4 py-2 rounded-lg font-semibold transition-colors ${
                          isDarkMode 
                            ? 'bg-red-600 hover:bg-red-700 text-white' 
                            : 'bg-red-500 hover:bg-red-600 text-white'
                        }`}
                      >
                        Close
                      </button>
                    </div>
                  )}
                </div>

                {/* Payment Instructions */}
                <div className={`p-4 rounded-2xl ${
                  isDarkMode ? 'bg-blue-900/30 border border-blue-800/50' : 'bg-blue-50 border border-blue-200'
                }`}>
                  <div className="flex items-start">
                    <svg className="w-5 h-5 text-blue-500 mr-3 mt-0.5" fill="none" stroke="currentColor" viewBox="0 0 24 24">
                      <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M13 16h-1v-4h-1m1-4h.01M21 12a9 9 0 11-18 0 9 9 0 0118 0z" />
                    </svg>
                    <div>
                      <h5 className={`font-semibold mb-2 ${isDarkMode ? 'text-white' : 'text-gray-800'}`}>
                        Payment Instructions
                      </h5>
                      <ul className={`text-sm space-y-1 ${isDarkMode ? 'text-gray-300' : 'text-gray-600'}`}>
                        <li>• Scan this QR code with any payment app</li>
                        <li>• Payment notification sent to admin</li>
                        <li>• Subscription will activate after payment confirmation</li>
                        <li>• Keep this window open until payment is complete</li>
                      </ul>
                    </div>
                  </div>
                </div>

                {/* Subscription Details */}
                {selectedPlan && (
                  <div className={`p-4 rounded-2xl ${
                    isDarkMode ? 'bg-gray-700/50' : 'bg-gray-50'
                  }`}>
                    <h5 className={`font-semibold mb-2 ${isDarkMode ? 'text-white' : 'text-gray-800'}`}>
                      Subscription Details
                    </h5>
                    <div className="flex justify-between items-center">
                      <span className={`text-sm ${isDarkMode ? 'text-gray-300' : 'text-gray-600'}`}>
                        {getPlanDetails(selectedPlan)?.name}
                      </span>
                      <span className="text-lg font-bold text-primary-600 dark:text-primary-400">
                        ₹{getPlanDetails(selectedPlan)?.price}
                      </span>
                    </div>
                    <div className={`text-xs mt-2 ${isDarkMode ? 'text-gray-400' : 'text-gray-500'}`}>
                      Subscription ID: {subscriptionId}
                    </div>
                  </div>
                )}
              </div>
            </div>

            {/* Modal Footer */}
            <div className="p-6 border-t border-gray-200/20 dark:border-gray-700/20">
              <div className="flex gap-3">
                <button
                  onClick={() => {
                    // Copy subscription ID to clipboard
                    if (subscriptionId) {
                      navigator.clipboard.writeText(subscriptionId);
                      alert('Subscription ID copied to clipboard!');
                    }
                  }}
                  className={`flex-1 py-3 px-4 rounded-xl font-semibold transition-colors ${
                    isDarkMode 
                      ? 'bg-gray-700 hover:bg-gray-600 text-white' 
                      : 'bg-gray-100 hover:bg-gray-200 text-gray-800'
                  }`}
                >
                  Copy ID
                </button>
                <button
                  onClick={() => {
                    // Check payment status
                    if (subscriptionId) {
                      window.location.href = `/subscription-status/${subscriptionId}`;
                    }
                  }}
                  className="flex-1 py-3 px-4 bg-gradient-to-r from-primary-500 to-secondary-500 text-white font-semibold rounded-xl hover:from-primary-600 hover:to-secondary-600 transition-all duration-300"
                >
                  Check Status
                </button>
              </div>
            </div>
          </div>
        </div>
      )}

      {/* Toast Container */}

      {toasts.map(toast => (

        <Toast

          key={toast.id}

          message={toast.message}

          type={toast.type}

          duration={toast.duration}

          onClose={() => removeToast(toast.id)}

        />

      ))}

    </div>

  );

};



export default Home;
